<script setup lang="ts">
const games=ref<any[]>([]),game=ref<any>(null),events=ref<any[]>([]),world=ref<any[]>([]),ledger=ref<any[]>([])
const tab=ref('overview'),busy=ref(false),error=ref(''),name=ref('Vanguard Security'),seed=ref('asterra-01'),batch=ref(4),stop=ref(true),result=ref<any>(null),selectedCountry=ref(''),showCreate=ref(false)
const nav=[['overview','◈','Visão geral'],['world','◎','Mundo'],['operators','♙','Operadores'],['contracts','▤','Contratos'],['operations','⌁','Operações'],['finance','▥','Finanças']]
const currency=(value:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value/100)
const date=computed(()=>game.value?new Date(game.value.date).toLocaleString('pt-BR',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'')
const country=computed(()=>world.value.find(c=>c.id===selectedCountry.value)||world.value[0])
const pendingAdvance=ref<any>(null)
const pendingCreation=ref<any>(null)
const personnelSummary=ref<any>({}),personnelWorking=ref(false)
const entryName=(type:string)=>(({initial_capital:'Capital inicial',signing_bonus:'Bônus de assinatura',salary_payment:'Pagamento salarial'} as Record<string,string>)[type]||type)
async function api(path:string,options:any={}){return await $fetch<any>('/api/v1'+path,options)}
async function load(){games.value=await api('/games')}
async function select(id:string){busy.value=true;error.value='';try{game.value=await api('/games/'+id);[events.value,world.value,ledger.value,personnelSummary.value]=await Promise.all([api(`/games/${id}/timeline`),api(`/games/${id}/world/countries`),api(`/games/${id}/finances/ledger`),api(`/games/${id}/finances/summary`)]);localStorage.setItem('operators-game',id);pendingAdvance.value=null;result.value=null;return true}catch(e:any){error.value=e.data?.message||'Não foi possível abrir a partida.';return false}finally{busy.value=false}}
async function create(){
 if(busy.value||personnelWorking.value)return;
 busy.value=true;error.value='';
 try{
  const command=pendingCreation.value||{requestId:crypto.randomUUID(),name:name.value,seed:seed.value};
  pendingCreation.value=command;
  const created=await api('/games',{method:'POST',body:command});
  await load();
  if(!await select(created.id))return;
  pendingCreation.value=null;showCreate.value=false;
 }catch(e:any){
  if(e.status>=400&&e.status<500)pendingCreation.value=null;
  error.value=e.data?.message||'Falha de conexão. Tente novamente para recuperar a mesma criação.';
 }finally{busy.value=false}
}
async function advance(){if(!game.value||busy.value||personnelWorking.value)return;busy.value=true;error.value='';try{const command=pendingAdvance.value||{requestId:crypto.randomUUID(),expectedVersion:game.value.stateVersion,turns:Number(batch.value),stopOnImportant:stop.value};pendingAdvance.value=command;const r=await api(`/games/${game.value.id}/advance`,{method:'POST',body:command});const id=game.value.id;await select(id);result.value=r;pendingAdvance.value=null}catch(e:any){error.value=e.data?.message||'Falha de conexão. Tente novamente para consultar a mesma requisição.';if(e.status===409){pendingAdvance.value=null;await select(game.value.id);error.value='A partida foi alterada. Dados atualizados; revise antes de avançar.'}}finally{busy.value=false}}
async function resume(){busy.value=true;error.value='';try{const r=await api(`/games/${game.value.id}/advances/${result.value.requestId}/resume`,{method:'POST',body:{expectedVersion:game.value.stateVersion}});await select(game.value.id);result.value=r}catch(e:any){error.value=e.data?.message||'Não foi possível retomar.'}finally{busy.value=false}}
onMounted(async()=>{try{await load();const id=localStorage.getItem('operators-game');if(id&&games.value.some(g=>g.id===id))await select(id);else if(games.value.length)await select(games.value[0].id)}catch{error.value='Não foi possível conectar. Atualize a página para tentar novamente.'}})
</script>
<template>
<div class="shell">
 <aside><a class="brand" href="/">OPERATORS<span>PMC COMMAND</span></a><div class="workspace-label">CENTRO DE COMANDO</div><nav><button v-for="item in nav" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]"><span>{{item[1]}}</span>{{item[2]}}<small v-if="['contracts','operations'].includes(item[0])">EM BREVE</small></button></nav><div class="aside-bottom"><span class="live-dot"></span> ACESSO PRIVADO<div>Gestão de pessoal · v0.2.0</div></div></aside>
 <main><header><div class="breadcrumb">ASTERRA <span>/</span> {{game?.name||'Nova companhia'}}</div><div class="header-status">SINGLE PLAYER <span>•</span> TEMPO MANUAL</div></header>
 <div class="content"><div class="page-heading"><div><div class="eyebrow">OPERAÇÃO INDEPENDENTE</div><h1>{{tab==='overview'?'Painel de comando':nav.find(n=>n[0]===tab)?.[2]}}</h1><p>Decisões estratégicas. Consequências persistentes.</p></div><button class="secondary" @click="showCreate=!showCreate">＋ Nova partida</button></div>
 <div v-if="error" role="alert" class="error">{{error}}</div>
 <section v-if="!game||showCreate" class="panel create"><div><span class="eyebrow">INICIAR CAMPANHA</span><h2>Sua companhia começa aqui.</h2><p>Crie um save com semente determinística. Cada turno representa 6 horas.</p></div><form @submit.prevent="create"><label>Nome da companhia<input v-model="name" :disabled="busy||!!pendingCreation" required minlength="2" maxlength="60"></label><label>Semente da campanha<input v-model="seed" :disabled="busy||!!pendingCreation" required maxlength="100"></label><button class="primary" :disabled="busy">{{busy?'Criando…':pendingCreation?'Repetir criação':'Estabelecer companhia →'}}</button></form></section>
 <template v-if="game">
 <div class="campaign-bar"><label>COMPANHIA<select :value="game.id" :disabled="busy||personnelWorking" @change="select(($event.target as HTMLSelectElement).value)"><option v-for="g in games" :key="g.id" :value="g.id">{{g.name}}</option></select></label><span><i class="live-dot"></i> {{game.status==='financial_crisis'?'CRISE FINANCEIRA':'CAMPANHA ATIVA'}}</span><span>REGRAS {{game.rulesVersion}}</span></div>
 <template v-if="tab==='overview'">
 <div class="stats"><section class="stat"><span>CAIXA DISPONÍVEL</span><strong>{{currency(game.cashCents)}}</strong><small>{{personnelSummary.employed||0}} vínculos ativos</small></section><section class="stat"><span>REPUTAÇÃO GLOBAL</span><strong>{{game.reputation}}<em>/ 100</em></strong><small>Companhia recém-estabelecida</small></section><section class="stat"><span>TURNO ATUAL</span><strong>{{String(game.currentTurn).padStart(3,'0')}}</strong><small>Semana {{Math.floor(game.currentTurn/28)+1}} · {{game.currentTurn*6}} horas decorridas</small></section><section class="stat"><span>QUADRO DE OPERADORES</span><strong>{{personnelSummary.employed||0}}<em> / {{personnelSummary.capacity||12}}</em></strong><small>Operadores com vínculo ativo</small></section></div>
 <section class="time-panel"><div><div class="eyebrow">CONTROLE TEMPORAL</div><h2>{{date}} <small>UTC do jogo</small></h2><p>O mundo avança somente sob seu comando.</p></div><div class="time-actions"><div class="advance-row"><select v-model.number="batch" aria-label="Quantidade de turnos" :disabled="busy"><option :value="1">1 turno · 6 horas</option><option :value="4">4 turnos · 1 dia</option><option :value="28">28 turnos · 1 semana</option></select><button class="primary" :disabled="busy||personnelWorking" @click="advance">{{busy?'Processando…':pendingAdvance?'Repetir requisição':'Avançar tempo →'}}</button></div><label class="check"><input v-model="stop" type="checkbox"> Interromper ao encontrar um evento importante</label></div></section>
 <div v-if="result" class="batch-result" role="status"><strong>{{result.status==='completed'?'Avanço concluído':result.status==='failed'?'Lote interrompido por falha':'Evento importante'}}</strong> · {{result.processedTurns}} de {{result.requestedTurns}} turnos confirmados. Turno atual: {{result.currentTurn}}.<button v-if="result.status==='failed'" @click="resume" :disabled="busy">Retomar restantes</button></div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h2>Registro de comando</h2><span class="tag">HISTÓRICO</span></div><div v-if="!events.length" class="empty"><div class="empty-icon">⌁</div><h3>Aguardando seu primeiro comando</h3><p>Avance o tempo para registrar os primeiros eventos da campanha.</p></div><div v-for="event in events.slice(0,8)" :key="`${event.turn}-${event.sequence}`" class="event"><span class="event-marker" :class="{important:event.important}"></span><div><div class="event-title">{{event.title}}<small>T{{String(event.turn).padStart(3,'0')}}</small></div><p>{{event.description}}</p></div></div></section><div class="right-stack"><section class="panel briefing"><div class="eyebrow">SITUAÇÃO ATUAL</div><h2>Gestão da companhia.</h2><p>Campanha persistente, pessoal e folha salarial integrados ao relógio.</p><div class="brief-line"><span>Persistência</span><strong>Salvamento online</strong></div><div class="brief-line"><span>Avanço</span><strong>1 a 28 turnos</strong></div><div class="brief-line"><span>Próxima fase</span><strong>Contratos e missões</strong></div></section><section class="panel note"><span class="eyebrow">ESCOPO DESTA VERSÃO</span><p>Operadores, recrutamento, salários e equipes disponíveis. Contratos comerciais, missões, crises mundiais, sede e kits entram nas próximas fases.</p></section></div></div>
 </template>
 <template v-else-if="tab==='world'"><div class="section-intro"><h2>Conheça Asterra</h2><p>Estrutura inicial do mundo. Indicadores, conflitos e influência entram na fase de simulação mundial.</p></div><div class="world-layout"><div class="country-list"><button v-for="c in world" :key="c.id" :class="{selected:country?.id===c.id}" @click="selectedCountry=c.id"><span>◎</span><div><strong>{{c.name}}</strong><small>3 regiões</small></div><span>→</span></button></div><section v-if="country" class="panel"><span class="eyebrow">DOSSIÊ REGIONAL</span><h2>{{country.name}}</h2><p>{{country.description}}</p><div v-for="(r,index) in country.regions" :key="r.id" class="region"><span>0{{Number(index)+1}}</span><div><h3>{{r.name}}</h3><p>Informações operacionais ainda não coletadas</p></div><span class="tag">SEM INTEL</span></div></section></div></template>
 <PersonnelPanel v-else-if="tab==='operators'" :game="game" @changed="select(game.id)" @processing="personnelWorking=$event" />
 <template v-else-if="tab==='finance'"><div class="stats finance-stats"><section class="stat"><span>SALDO EM CAIXA</span><strong>{{currency(game.cashCents)}}</strong><small>Valores fictícios em USD</small></section><section class="stat"><span>DESPESA SEMANAL</span><strong>{{currency(personnelSummary.weeklySalaryCents||0)}}</strong><small>Salários dos vínculos ativos</small></section><section v-if="personnelSummary.arrearsCents" class="stat"><span>DÍVIDA SALARIAL</span><strong>{{currency(personnelSummary.arrearsCents)}}</strong><small>Quitação automática quando houver caixa suficiente</small></section></div><section class="panel"><div class="panel-heading"><h2>Livro-razão</h2><span class="tag">AUDITÁVEL</span></div><table><thead><tr><th>TURNO</th><th>LANÇAMENTO</th><th>VALOR</th></tr></thead><tbody><tr v-for="entry in ledger" :key="entry.sourceId"><td data-label="Turno">{{entry.turn}}</td><td data-label="Lançamento">{{entryName(entry.entryType)}}</td><td data-label="Valor" :class="entry.amountCents<0?'debit':'credit'">{{currency(entry.amountCents)}}</td></tr></tbody></table></section></template>
 <section v-else class="panel unavailable"><div class="empty-icon">◇</div><span class="eyebrow">MÓDULO EM DESENVOLVIMENTO</span><h2>{{nav.find(n=>n[0]===tab)?.[2]}}</h2><p>{{tab==='operators'?'O próximo incremento adicionará recrutamento, fichas e equipes permanentes.':tab==='contracts'?'O catálogo e o planejamento serão implementados após operadores e equipes.':'As operações autônomas dependem do planejamento e do motor de missões.'}}</p><button class="secondary" @click="tab='overview'">Voltar ao comando</button></section>
 </template>
 <footer><span>OPERATORS <b> / </b> PMC COMMAND</span><span>PESSOAL · 0.2.0</span></footer></div>
 </main>
</div>
</template>
